import type { Meta, StoryObj } from "@storybook/vue3";
import { KozmosBox, KozmosStack } from "../../index";

/**
 * Vue's Stack: the stories React's has, with the same names and args, each
 * inside the KozmosThemeProvider the Storybook's decorator gives every
 * story. React's stories draw their items as JSX children, so each is drawn
 * here as React's draws it, from KozmosBox; test/parity/stack.parity.spec.ts
 * holds Vue's render to React's. Generated by `port Stack`, then drawn by
 * hand.
 */
type Args = Record<string, unknown>;

const meta: Meta<Args> = {
  title: "Vue/Core/Layout/Stack",
  component: KozmosStack,
  argTypes: {
    direction: { control: "radio", options: ["row", "column"] },
    gap: { control: "select", options: [0, 1, 2, 4, 8] },
  },
  // React's BoxItem: the theme fill under the theme foreground, white in
  // both themes (decision 59), then the secondary and accent fills.
  render: (args) => ({
    components: { KozmosBox, KozmosStack },
    setup: () => ({ args }),
    template: `
      <KozmosStack v-bind="args">
        <KozmosBox class="p-4 rounded text-theme-fill-foreground bg-theme-fill">Item 1</KozmosBox>
        <KozmosBox class="p-4 rounded text-secondary-foreground bg-secondary">Item 2</KozmosBox>
        <KozmosBox class="p-4 rounded text-accent-foreground bg-accent">Item 3</KozmosBox>
      </KozmosStack>
    `,
  }),
};

export default meta;
type Story = StoryObj<Args>;

/** React's Default: a column of three items, 8 apart. */
export const Default: Story = { args: {} };

/** React's Horizontal: a row of three items, 16 apart. */
export const Horizontal: Story = { args: { direction: "row", gap: 4 } };
